contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function test(address vader, address usdv, address vault, address recipient, uint amount) public {
        require(amount > 0);
        c.init(vader, usdv, vault);
        c.newGrantProposal(recipient, amount);
        c.voteProposal(1);
        c.finaliseProposal(1);
        assert(c.VADER() == vader);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function test(address _vader, address _usdv, address _vault, address proposedAddress) public returns (bool) {
        c.init(_vader, _usdv, _vault);
        c.newAddressProposal(proposedAddress, "UTILS");
        uint pid = c.proposalCount();
        c.voteProposal(pid);
        bool success = !address(c).balance;
        c.finaliseProposal(pid);
        return success;
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address _vader, address _usdv, address _vault) public payable {
        require(true);
        c.init(_vader, _usdv, _vault);
        assert(c.VADER() != address(0));
    }
}

contract InvMutTest {
    C c;
    bool initReverted;
    constructor(C _c) { c = _c; }
    function test(address _vader, address _usdv, address _vault, address recipient, uint amount) public {
        try c.init(_vader, _usdv, _vault) { initReverted = false; } catch { initReverted = true; }
        if (!initReverted) {
            c.newGrantProposal(recipient, amount);
            try c.finaliseProposal(1) { assert(false); } catch { assert(true); }
        }
    }
}

